#!/bin/bash
# The 40 great ruler portraits in the Octopath style, generated 8 at a time.
# Skips any portrait that already exists, so it can be re-run to fill gaps.
OUT=/Users/arielindra/Documents/Projects/Realmforge/.claude/worktrees/realm-forge-art-direction-0a7149/assets/portrait-drafts/octo-great
GEN=~/.claude/skills/gpt-image-bridge/bin/gpt-image-2
mkdir -p "$OUT"

FRAME="Vertical half-body character portrait for a fantasy grand-strategy game. Crop from just above the head to the waist, face large and clear in the upper third, any crown or headdress fully inside the image. Figure centered, body turned slightly three-quarters, looking at the viewer. Simple dark background with no scenery. No text, no logo, no border, no watermark."
STYLE="Style: HD-2D JRPG character portrait in the spirit of Octopath Traveler: high-resolution hand-placed pixel art with visible crisp square pixels, limited rich palette, strong dithering, sharp silhouette, dramatic lantern lighting, painterly 16-bit portrait quality, dark vignette background with a subtle soft glow behind the figure. It must clearly read as pixel art, not a painting."
SEXY="Functional yet glamorous, confident and sensual, tasteful, no nudity."

