run() {
  if [ -f "$OUT/$1.png" ]; then echo "exists: $1"; return; fi
  var="S_${1//-/_}"
  subject="${!var}"
  if [ -z "$subject" ]; then echo "NO SUBJECT: $1"; return; fi
  # DRY=1 only prints what would be generated.
  if [ -n "$DRY" ]; then echo "$1: ${subject:9:50}"; return; fi
  "$GEN" "$FRAME $subject $STYLE" "$OUT/$1.png" --size 1024x1536 > /dev/null 2>&1 && echo "done: $1" || echo "FAILED: $1"
}

ALL="human-m-conqueror human-f-conqueror human-m-lawgiver human-f-lawgiver human-m-builder human-f-builder human-m-prophet human-f-prophet human-m-schemer human-f-schemer
lelf-m-conqueror lelf-f-conqueror lelf-m-lawgiver lelf-f-lawgiver lelf-m-builder lelf-f-builder lelf-m-prophet lelf-f-prophet lelf-m-schemer lelf-f-schemer
delf-m-conqueror delf-f-conqueror delf-m-lawgiver delf-f-lawgiver delf-m-builder delf-f-builder delf-m-prophet delf-f-prophet delf-m-schemer delf-f-schemer
orc-m-conqueror orc-m-lawgiver orc-m-builder orc-m-prophet orc-m-schemer dwarf-m-conqueror dwarf-m-lawgiver dwarf-m-builder dwarf-m-prophet dwarf-m-schemer"

# Eight at a time, so the image service isn't flooded.
count=0
for name in $ALL; do
  run "$name" &
  count=$((count + 1))
  if [ $((count % 8)) -eq 0 ]; then wait; fi
done
wait
echo "total: $(ls "$OUT"/*.png 2>/dev/null | wc -l)"
